        width: 40px;
        height: 40px;
    }

    .epg-timeline {
        gap: 8px;
    }

    .action-buttons {
        gap: 0;
    }
}

@container (max-width: 310px) {
    .epg-timeline {
        grid-template-columns: 1fr;
        gap: 5px;
    }

    .epg-time:last-child {
        display: none;
    }
}

@container (max-width: 270px) {
    .channel-list-item {
        min-height: 52px;
        gap: 8px;
        padding-inline: 8px 6px;
    }

    .channel-logo-shell {
        width: 34px;
        height: 34px;
    }

    .epg-title,
    .epg-timeline,
    .epg-placeholder,
    .program-info-button {
        display: none;
    }
}

@container (max-width: 220px) {
    .channel-logo-shell,
    .action-buttons {
        display: none;
    }

    .channel-content {
        gap: 0;
    }
}

