:host {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    min-height: 0;
    overflow-x: hidden;
    background: transparent;
}

#date-navigator {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 10px 10px;
    gap: 8px;

    button {
        border-radius: 10px;
        opacity: 0.84;
        transition:
            opacity 0.15s ease,
            background-color 0.15s ease,
            transform 0.15s ease;

        &:hover:not([disabled]) {
            opacity: 1;
            background: color-mix(in srgb, currentColor 10%, transparent);
            transform: translateY(-1px);
        }

        &[disabled] {
            opacity: 0.3;
        }
    }
}

.selected-date {
    flex: 1;
    text-align: center;
    font-size: 0.83rem;
    line-height: 1.2;
    font-weight: 600;
    letter-spacing: 0.01em;
    opacity: 0.8;
}

#program-list {
    flex: 1;
    overflow-y: scroll;
    overflow-x: hidden;
