    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--app-muted-color) 55%, transparent)
        transparent;

    &::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }

    &::-webkit-scrollbar-track {
        background: transparent;
    }

    &::-webkit-scrollbar-thumb {
        background-color: color-mix(
            in srgb,
