// rules outrank the global `.dark-theme ::-webkit-scrollbar` block below.
.app-scrollbar {
    overflow-y: scroll;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--app-muted-color) 55%, transparent)
        transparent;
}

