// ─── Shared Components ────────────────────────────────────────────────────────

// Always-visible themed scrollbar. Apply to scroll containers that should
// reserve gutter and not rely on macOS overlay scrollbars (which auto-fade).
// Selector is doubled (.app-scrollbar.app-scrollbar) throughout so the rules
// outrank both component-scoped overflow declarations and the global
// `.dark-theme ::-webkit-scrollbar` block below.
.app-scrollbar.app-scrollbar {
    overflow-y: scroll;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--app-muted-color) 55%, transparent)
        transparent;

    &::-webkit-scrollbar {
        width: 10px;
        height: 10px;
    }

    &::-webkit-scrollbar-track {
        background: transparent;
    }

    &::-webkit-scrollbar-thumb {
        background-color: color-mix(
            in srgb,
            var(--app-muted-color) 70%,
            transparent
        );
        border-radius: 999px;
        border: 2px solid transparent;
        background-clip: content-box;
        min-height: 32px;

        &:hover {
            background-color: var(--app-muted-color);
            background-clip: content-box;
        }
    }
}

app-root.macos-platform .current-playlist {
    padding-top: 30px;
}

