    background: var(--mat-sys-surface-container-low);
    border-bottom: 1px solid var(--mat-sys-outline-variant);
    min-height: 40px;
}

.player-title {
    flex: 1;
    min-width: 0;
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--mat-sys-on-surface);
}

.close-btn {
    flex-shrink: 0;
}

.radio-close-btn {
    position: absolute;
    top: 16px;
    right: 16px;
    z-index: 4;
    color: var(--mat-sys-on-surface);
    background: color-mix(
        in srgb,
        var(--mat-sys-surface-container-high) 72%,
        transparent
    );
    backdrop-filter: blur(12px);
}

.epg {
    border-top: 1px solid var(--mat-sys-outline-variant);
    background: var(--mat-sys-surface);
    display: flex;
    flex-direction: column;
}

.epg-content {
    flex: 1;
    min-height: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;

    > app-epg-view,
    > app-epg-list {
        flex: 1;
        min-height: 0;
    }
}
